def is_lucky_digit(digit):
    return digit == '4' or digit == '7'

def count_lucky_digits(number):
    return sum(1 for digit in str(number) if is_lucky_digit(digit))

def is_lucky_number(n):
    return n == 4 or n == 7

def is_nearly_lucky_number(n):
    lucky_digit_count = count_lucky_digits(n)
    return is_lucky_number(lucky_digit_count)

def main():
    n = int(input())
    if is_nearly_lucky_number(n):
        print('YES')
    else:
        print("NO")

if __name__ == "__main__":
    main()

def is_lucky_digit(digit):
    return digit == '4' or digit == '7'

def count_lucky_digits(number):
    count = 0
    for digit in str(number):
        if is_lucky_digit(digit):
            count += 1
    return count

def is_lucky(num):
    return num == 4 or num == 7

def is_nearly_lucky(number):
    lucky_digit_count = count_lucky_digits(number)
    return is_lucky(lucky_digit_count)

def main():
    n = int(input())

    if is_nearly_lucky(n):
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()

